/*
 * prog41_series_sum – reconstructed from the obfuscated binary.
 *
 * The program expects exactly two command‑line arguments:
 *   1. mode  – an integer selecting the series to sum
 *   2. n     – the number of terms (non‑negative, at most 100 000)
 *
 * Behaviour (matching the original binary):
 *
 *   * If fewer than two arguments are supplied:
 *         prints "NO_INPUT" and exits.
 *
 *   * If either argument cannot be parsed as a decimal integer
 *     (or contains extra characters):
 *         prints "BAD_INPUT" and exits.
 *
 *   * If n > 100000:
 *         prints "OUT_OF_RANGE" and exits.
 *
 *   * If n < 0:
 *         prints "BAD_INPUT" and exits.
 *
 *   * Supported modes:
 *         1 – sum of 1/(k*k)   for k = 1 .. n
 *         2 – sum of 1/k       for k = 1 .. n
 *         3 – sum of 1/k       for k = 1 .. n   (identical to mode 2)
 *
 *   * Any other mode:
 *         prints "BAD_MODE" and exits.
 *
 *   * For the supported modes the result is printed with six
 *     digits after the decimal point, exactly as the original
 *     program does (printf("%.6f\n", sum);).
 *
 * The implementation below follows the logic of the decompiled
 * state‑machine while using straightforward C constructs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* Argument count check – matches the original “NO_INPUT” case. */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the two integer arguments safely. */
    char *endptr1, *endptr2;
    errno = 0;
    long mode = strtol(argv[1], &endptr1, 10);
    long n    = strtol(argv[2], &endptr2, 10);

    /* Detect conversion errors or trailing characters. */
    if (errno != 0 ||
        endptr1 == argv[1] || *endptr1 != '\0' ||
        endptr2 == argv[2] || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Range checks for the number of terms. */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Compute the requested series. */
    double sum = 0.0;

    switch (mode) {
        case 1:   /* sum of 1/(k*k) */
            for (long k = 1; k <= n; ++k) {
                sum += 1.0 / ((double)k * (double)k);
            }
            break;

        case 2:   /* harmonic series */
        case 3:   /* harmonic series – same as mode 2 in the original */
            for (long k = 1; k <= n; ++k) {
                sum += 1.0 / (double)k;
            }
            break;

        default:
            puts("BAD_MODE");
            return 0;
    }

    /* Output the result with six fractional digits. */
    printf("%.6f\n", sum);
    return 0;
}
